package dev.eugheist.tc4modern;
import java.util.*;
import net.minecraft.core.*;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.item.*;
import net.minecraft.world.level.block.Blocks;
import net.minecraft.world.level.block.state.properties.BlockStateProperties;
import net.neoforged.bus.api.SubscribeEvent;
import net.neoforged.fml.common.EventBusSubscriber;
import thaumcraft.api.aspects.Aspect;
@EventBusSubscriber(modid=TC4Modern.MODID,value=net.neoforged.api.distmarker.Dist.CLIENT)
final class FluxScrubberAudit {
 static final BlockPos POS=FocalAudit.BASE.offset(44,1,64),FLUX=POS.east(3);static int ticks;static volatile boolean prepared,cleaned,transported;static FluxScrubber.ScrubberEntity tile;
 static void check(boolean b,String s){if(!b)throw new IllegalStateException("TC4_SCRUBBER FAIL "+s);System.out.println("TC4_SCRUBBER PASS "+s);}
 static void queue(BlockPos... ps){tile.checklist.clear();tile.checklist.addAll(List.of(ps));tile.cursor=0;}
 static void prepare(ServerPlayer p){var l=p.serverLevel();p.setGameMode(net.minecraft.world.level.GameType.CREATIVE);p.getAbilities().flying=true;p.onUpdateAbilities();p.removeAllEffects();p.getInventory().clearContent();for(var cat:thaumcraft.api.research.ResearchCategories.researchCategories.values())for(var r:cat.research.values())DevCommands.grant(p.getPersistentData(),r.key,new HashSet<>());ThaumometerItem.sync(p,"");for(int x=-5;x<=5;x++)for(int z=-4;z<=4;z++)for(int y=-1;y<=4;y++)l.setBlock(POS.offset(x,y,z),y==-1?Blocks.STONE.defaultBlockState():Blocks.AIR.defaultBlockState(),2);
  l.setBlock(POS,FluxScrubber.BLOCK.get().defaultBlockState().setValue(BlockStateProperties.FACING,Direction.EAST),3);tile=(FluxScrubber.ScrubberEntity)l.getBlockEntity(POS);tile.power=20;
  l.setBlock(FLUX,TC4Modern.FLUX_GOO.get().defaultBlockState().setValue(FluxBlock.AMOUNT,3),2);queue(FLUX);tile.checkFlux();check(l.getBlockState(FLUX).getValue(FluxBlock.AMOUNT)==2&&tile.power==15&&tile.charges==1,"five aer removes exactly one goo unit");
  l.setBlock(FLUX,TC4Modern.FLUX_GAS.get().defaultBlockState(),2);queue(FLUX);tile.checkFlux();check(l.isEmptyBlock(FLUX)&&tile.charges==2,"last gas unit becomes air");
  var edge=POS.east(16);l.setBlock(edge,TC4Modern.FLUX_GOO.get().defaultBlockState(),2);queue(edge);tile.checkFlux();check(!l.isEmptyBlock(edge)&&tile.power==10,"strict radius16 excludes boundary");l.removeBlock(edge,false);
  var slots=new ArrayList<BlockPos>();for(int i=0;i<16;i++)slots.add(POS.offset(i,4,0));slots.add(FLUX);l.setBlock(FLUX,TC4Modern.FLUX_GAS.get().defaultBlockState(),2);tile.checklist.clear();tile.checklist.addAll(slots);tile.cursor=0;tile.checkFlux();check(tile.cursor==16&&!l.isEmptyBlock(FLUX),"scan examines at most16candidates per tick");tile.checkFlux();check(l.isEmptyBlock(FLUX)&&tile.charges==3,"next scan processes seventeenth candidate");
  tile.essentia=4;for(var d:Direction.values())check(tile.isConnectable(d)==(d==Direction.EAST)&&tile.canOutputTo(d)==(d==Direction.EAST)&&!tile.canInputFrom(d),"only facing output "+d);check(tile.getEssentiaType(Direction.EAST)==Aspect.MAGIC&&tile.takeEssentia(Aspect.FIRE,2,Direction.WEST)==2&&tile.essentia==2,"original take ignores wrong aspect and face");check(tile.addEssentia(Aspect.MAGIC,4,Direction.EAST)==0,"never accepts essentia");
  tile.charges=4;tile.power=0;var saved=tile.saveWithFullMetadata(l.registryAccess());var copy=new FluxScrubber.ScrubberEntity(POS,tile.getBlockState());copy.loadWithComponents(saved,l.registryAccess());check(copy.charges==4&&copy.essentia==2&&copy.power==0&&copy.facing()==Direction.EAST&&copy.checklist.isEmpty(),"power charges essentia facing persist, scan list resets");
  int produced=0;for(int i=0;i<128;i++){tile.charges=4;tile.essentia=0;FluxScrubber.ScrubberEntity.tick(l,POS,tile.getBlockState(),tile);check(tile.charges==0,"four charges consumed roll "+i);produced+=tile.essentia;}check(produced>10&&produced<60,"original25percent conversion observed over128rolls");tile.charges=0;tile.essentia=0;
  var nodePos=POS.west(3).above();l.setBlock(nodePos,TC4Modern.ENERGIZED_NODE.get().defaultBlockState(),3);var node=(EnergizedNodeEntity)l.getBlockEntity(nodePos);node.auraBase.add(Aspect.AIR,100);node.energy.visBase.add(Aspect.AIR,10);node.energy.vis.add(Aspect.AIR,10);VisNetwork.register(l,node);VisNetwork.invalidate();
  l.setBlock(FLUX,TC4Modern.FLUX_GOO.get().defaultBlockState().setValue(FluxBlock.AMOUNT,3),2);tile.power=0;queue(FLUX);FluxScrubber.ScrubberEntity.tick(l,POS,tile.getBlockState(),tile);check(tile.power==5&&l.getBlockState(FLUX).getValue(FluxBlock.AMOUNT)==2,"actual vis network drains10aer then spends5 to clean flux");l.removeBlock(nodePos,false);
  // Natural server ticking with a tiny deterministic scan queue; enclosed gas cannot escape.
  for(var d:Direction.values())l.setBlock(FLUX.relative(d),Blocks.GLASS.defaultBlockState(),2);l.setBlock(FLUX,TC4Modern.FLUX_GAS.get().defaultBlockState().setValue(FluxBlock.AMOUNT,3),2);queue(FLUX,FLUX,FLUX);tile.power=15;tile.charges=0;
  var r=ArcaneRecipes.entries().stream().filter(e->e.key().equals("FluxScrubber")).findFirst().orElseThrow();var grid=r.ingredients().stream().map(i->i.isEmpty()?ItemStack.EMPTY:i.getItems()[0].copy()).toList();check(r.matches(grid,Set.of("FLUXSCRUB"))&&!r.matches(grid,Set.of()),"real arcane scrubber recipe research gate");p.connection.teleport(POS.getX()+5,POS.getY()+3,POS.getZ()-6,40,20);p.getInventory().setItem(0,new ItemStack(FluxScrubber.BLOCK.get()));p.getInventory().selected=8;prepared=true;
 }
 @SubscribeEvent static void tick(net.neoforged.neoforge.client.event.ClientTickEvent.Post e){if(!Boolean.getBoolean("tc4modern.scrubberAuditOnly"))return;var mc=net.minecraft.client.Minecraft.getInstance();if(mc.player==null||mc.level==null)return;ticks++;var server=mc.getSingleplayerServer();var id=mc.player.getUUID();if(ticks==80)server.execute(()->prepare(server.getPlayerList().getPlayer(id)));if(ticks==110){check(prepared,"server setup complete");LiquidDeathAudit.shot(mc,"flux-scrubber.png");}if(ticks==120)server.execute(()->{check(server.overworld().isEmptyBlock(FLUX)&&tile.charges==3&&tile.power==0,"natural ticks remove3gasunits with15aer");cleaned=true;});if(ticks==125)server.execute(()->{var l=server.overworld();tile.essentia=4;l.setBlock(POS.east(),EssentiaTubes.TUBE.get().defaultBlockState(),3);l.setBlock(POS.east().below(),EssentiaDevices.JAR.get().defaultBlockState(),3);var jar=(WardedJarEntity)l.getBlockEntity(POS.east().below());jar.state.aspect=Aspect.MAGIC;jar.state.aspectFilter=Aspect.MAGIC;jar.changed();});if(ticks==225)server.execute(()->{var jar=(WardedJarEntity)server.overworld().getBlockEntity(POS.east().below());check(tile.essentia==0&&jar.state.amount==4&&jar.state.aspect==Aspect.MAGIC,"actual tube transports all4Praecantatio into warded jar");transported=true;});if(ticks==230){check(transported,"native tube transfer completed");LiquidDeathAudit.shot(mc,"flux-scrubber-tube.png");check(cleaned,"natural cleaning completed");var inv=mc.player.getInventory();var book=new ThaumonomiconScreen(new ThaumonomiconMenu(0,inv),inv,net.minecraft.network.chat.Component.empty());book.auditOpen(thaumcraft.api.research.ResearchCategories.getResearch("FLUXSCRUB"),0);mc.setScreen(book);}if(ticks==240)LiquidDeathAudit.shot(mc,"flux-scrubber-book.png");if(ticks==250)mc.stop();}
}
